package local.skyfamily;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.os.*;import android.view.SurfaceHolder;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public class CastService extends Service {
 static CastService instance;final Handler main=new Handler();final HashMap<String,UpnpRenderer> receivers=new HashMap<>();final ExecutorService images=Executors.newSingleThreadExecutor();MediaPlayer media;boolean prepared=false,photoMode=false;Bitmap photo;SurfaceHolder display;UpnpRenderer active;int generation=0;long nextScan=0;String detail="Starting receiver",title="legacydash",lastNotice="";
 static List<InetAddress> addresses(){ArrayList<InetAddress> list=new ArrayList<>();try{Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces.hasMoreElements()){NetworkInterface net=interfaces.nextElement();if(!net.isUp()||net.isLoopback())continue;Enumeration<InetAddress> ips=net.getInetAddresses();while(ips.hasMoreElements()){InetAddress ip=ips.nextElement();if(ip instanceof Inet4Address&&ip.isSiteLocalAddress())list.add(ip);}}}catch(Exception ignored){}Collections.sort(list,(a,b)->a.getHostAddress().compareTo(b.getHostAddress()));return list;}
 public void onCreate(){super.onCreate();instance=this;if(Build.VERSION.SDK_INT>=26){NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("legacydash.cast","legacydash receiver",NotificationManager.IMPORTANCE_LOW));}startForeground(1801,notice("Starting DLNA receiver"));main.post(tick);}
 Notification notice(String text){int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;Intent show=new Intent(this,CompanionActivity.class).putExtra("cast.view",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent open=PendingIntent.getActivity(this,1801,show,flags),stop=PendingIntent.getService(this,1802,new Intent(this,CastService.class).setAction("stop"),flags);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"legacydash.cast"):new Notification.Builder(this);return builder.setSmallIcon(R.drawable.ic_sky).setContentTitle("legacydash / DLNA receiver").setContentText(text).setContentIntent(open).setOngoing(true).addAction(android.R.drawable.ic_media_pause,"Stop receiving",stop).build();}
 public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"stop".equals(intent.getAction())){getSharedPreferences("sky",0).edit().putBoolean("cast.persistent",false).apply();stopSelf();return START_NOT_STICKY;}if(!getSharedPreferences("sky",0).getBoolean("cast.persistent",true)){stopSelf();return START_NOT_STICKY;}nextScan=0;return START_STICKY;}
 public IBinder onBind(Intent intent){return null;}
 String network(){return receivers.isEmpty()?"No active private IPv4 interface / waiting for network":"Discoverable on "+android.text.TextUtils.join(", ",new TreeSet<String>(receivers.keySet()));}
 void scan(){List<InetAddress> addresses=addresses();HashSet<String> live=new HashSet<>();for(InetAddress address:addresses)live.add(address.getHostAddress());for(String key:new ArrayList<String>(receivers.keySet()))if(!live.contains(key)){UpnpRenderer removed=receivers.remove(key);if(removed==active)active=null;removed.close();}android.content.SharedPreferences preferences=getSharedPreferences("sky",0);String uuid=preferences.getString("dlna.uuid","");if(uuid.isEmpty()){uuid=UUID.randomUUID().toString();preferences.edit().putString("dlna.uuid",uuid).apply();}String name=preferences.getString("dlna.name","legacydash");if(name.trim().isEmpty())name="legacydash";for(InetAddress address:addresses){String key=address.getHostAddress();if(receivers.containsKey(key))continue;try{final UpnpRenderer[] slot=new UpnpRenderer[1];slot[0]=new UpnpRenderer(getApplicationContext(),address,name,uuid,(action,args)->main.post(()->command(slot[0],action,args)));receivers.put(key,slot[0]);}catch(Exception error){detail="Receiver unavailable on "+key+" / "+error.getMessage();}}}
 void sync(UpnpRenderer source){if(source==null)return;for(UpnpRenderer receiver:receivers.values())if(receiver!=source){receiver.uri=source.uri;receiver.metadata=source.metadata;receiver.wantPlay=source.wantPlay;receiver.state=source.state;receiver.status=source.status;receiver.position=source.position;receiver.duration=source.duration;receiver.volume=source.volume;receiver.muted=source.muted;}}
 void command(UpnpRenderer source,String action,Map<String,String> args){if(source==null||!receivers.containsValue(source))return;active=source;sync(source);if(action.equals("SetAVTransportURI")){load(args.get("CurrentURI"),args.get("CurrentURIMetaData"));return;}try{if(action.equals("Play")){if(prepared&&media!=null)media.start();detail=prepared||photo!=null?"Playing":"Preparing received media";}else if(action.equals("Pause")){if(prepared&&media!=null)media.pause();detail="Paused";}else if(action.equals("Stop")){if(prepared&&media!=null){media.pause();media.seekTo(0);}detail="Stopped";}else if(action.equals("Seek")&&prepared&&media!=null)media.seekTo((int)Math.min(Integer.MAX_VALUE,source.position));else if(action.equals("SetVolume")||action.equals("SetMute"))volume();}catch(Exception error){fail("Playback command failed");}sync(source);}
 void releaseMedia(){generation++;prepared=false;if(media!=null){try{media.reset();media.release();}catch(Exception ignored){}media=null;}photo=null;}
 void load(String address,String metadata){releaseMedia();int stamp=generation;title="Received media";String mime="";if(metadata!=null)try{Map<String,String> values=UpnpRenderer.parse(metadata);if(values.containsKey("title"))title=values.get("title");if(metadata.contains("image/"))mime="image";}catch(Exception ignored){}String path=android.net.Uri.parse(address).getPath();path=path==null?"":path.toLowerCase(Locale.US);photoMode=mime.equals("image")||path.endsWith(".jpg")||path.endsWith(".jpeg")||path.endsWith(".png")||path.endsWith(".gif");detail=photoMode?"Loading received image":"Preparing received media";if(photoMode){images.submit(()->{try{Bitmap bitmap=downloadImage(address);main.post(()->{if(stamp!=generation){bitmap.recycle();return;}photo=bitmap;detail="Received image / open receiver to view";if(active!=null){active.state=active.wantPlay?"PLAYING":"STOPPED";sync(active);}});}catch(Exception error){main.post(()->{if(stamp==generation)fail("Received image unavailable");});}});return;}try{MediaPlayer player=new MediaPlayer();media=player;player.setAudioStreamType(AudioManager.STREAM_MUSIC);player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);if(display!=null&&display.getSurface().isValid())player.setDisplay(display);player.setOnPreparedListener(mp->{if(mp!=media||stamp!=generation)return;prepared=true;volume();if(active!=null){active.duration=Math.max(0,mp.getDuration());if(active.wantPlay){mp.start();active.state="PLAYING";}else active.state="STOPPED";sync(active);}detail="Received media ready";});player.setOnCompletionListener(mp->{if(mp!=media)return;detail="Playback finished";if(active!=null){active.state="STOPPED";active.wantPlay=false;sync(active);}});player.setOnErrorListener((mp,what,extra)->{if(mp==media)fail("Cannot play received URL or format on this device");return true;});player.setDataSource(this,android.net.Uri.parse(address));player.prepareAsync();}catch(Exception error){fail("Received media unavailable");}}
 Bitmap downloadImage(String address)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL(address).openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(15000);try{int status=connection.getResponseCode();if(status<200||status>=300)throw new IOException("HTTP "+status);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(bytes.size()+count>20000000)throw new IOException("Image too large");bytes.write(buffer,0,count);}}byte[] data=bytes.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<1||options.outHeight<1)throw new IOException("Unsupported image");options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1200||options.outHeight/options.inSampleSize>800)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap result=BitmapFactory.decodeByteArray(data,0,data.length,options);if(result==null)throw new IOException("Unsupported image");return result;}finally{connection.disconnect();}}
 void fail(String message){detail=message;if(active!=null){active.state="STOPPED";active.status="ERROR_OCCURRED";active.wantPlay=false;sync(active);}}
 void volume(){if(media!=null&&active!=null)try{float amount=active.muted?0:active.volume/100f;media.setVolume(amount,amount);}catch(Exception ignored){}}
 void attach(SurfaceHolder holder){if(display==holder)return;display=holder;if(media!=null)try{media.setDisplay(holder);}catch(Exception ignored){}}
 void detach(SurfaceHolder holder){if(display==holder){display=null;if(media!=null)try{media.setDisplay(null);}catch(Exception ignored){}}}
 void local(String action){if(active==null){detail="No media has been received";return;}try{HashMap<String,String> args=new HashMap<>();args.put("InstanceID","0");if(action.equals("Play"))args.put("Speed","1");active.act("avt",action,args);}catch(Exception error){detail="No playable media";}}
 void seek(int position){if(prepared&&media!=null)try{media.seekTo(position);}catch(Exception ignored){}}
 void setVolume(int amount){for(UpnpRenderer receiver:receivers.values())receiver.volume=amount;volume();}
 final Runnable tick=new Runnable(){public void run(){if(instance!=CastService.this)return;long now=SystemClock.elapsedRealtime();if(now>=nextScan){nextScan=now+15000;scan();}if(prepared&&media!=null&&active!=null)try{active.position=Math.max(0,media.getCurrentPosition());active.duration=Math.max(0,media.getDuration());sync(active);}catch(Exception ignored){}String message=network()+" / "+detail;if(!message.equals(lastNotice)){lastNotice=message;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(1801,notice(message));}main.postDelayed(this,1000);}};
 public void onDestroy(){instance=null;main.removeCallbacksAndMessages(null);for(UpnpRenderer receiver:receivers.values())receiver.close();receivers.clear();releaseMedia();images.shutdownNow();display=null;stopForeground(true);super.onDestroy();}
}
